            // Move the left subtree to the right
            curr.right = curr.left;

            // Left pointer must always be NULL
            curr.left = null;
        }

        // Move to the next node
        curr = curr.right;
    }
}

function printFlattenedTree(root)
{
    let res = "";
    while (root !== null) {
        res += root.data + " ";
        root = root.right;
    }

    console.log(res.trim());
}

